insert into public.games (slug, title, description, type, category, difficulty, xp_reward, data, sort) values ('quiz-literacy', 'Quiz Battle: Компьютерлік сауаттылық', 'Уақыт шектеулі 8 сұрақ. Жылдам әрі дұрыс жауап бер!', 'quiz', 'computer_literacy', 'easy', 60, '{"time_per_question":20,"questions":[{"q":"Файлды көшіру үшін қай пернелер тіркесі қолданылады?","options":["Ctrl + V","Ctrl + C","Ctrl + Z","Ctrl + X"],"answer":1,"explain":"Ctrl + C — көшіру, Ctrl + V — қою."},{"q":"Соңғы әрекетті болдырмау пернелері:","options":["Ctrl + Z","Ctrl + S","Alt + F4","Ctrl + P"],"answer":0,"explain":"Ctrl + Z — Undo, яғни болдырмау."},{"q":"Қай бағдарлама — операциялық жүйе?","options":["Word","Chrome","Windows","Paint"],"answer":2,"explain":"Windows, macOS, Linux — операциялық жүйелер."},{"q":".docx кеңейтімі қай файлға тиесілі?","options":["Сурет","Мәтіндік құжат","Музыка","Бейне"],"answer":1,"explain":".docx — Microsoft Word құжаты."},{"q":"Қалта (папка) не үшін керек?","options":["Файлдарды реттеп сақтау","Интернетке қосылу","Вирусты жою","Экранды үлкейту"],"answer":0,"explain":"Қалталар файлдарды топтап, реттеуге көмектеседі."},{"q":"Құжатты сақтау пернелері:","options":["Ctrl + O","Ctrl + N","Ctrl + S","Ctrl + A"],"answer":2,"explain":"Ctrl + S — Save, сақтау."},{"q":"Себет (Корзина) не сақтайды?","options":["Жүктелген ойындарды","Жойылған файлдарды","Құпиясөздерді","Интернет беттерін"],"answer":1,"explain":"Жойылған файлдар алдымен Себетке түседі, оларды қалпына келтіруге болады."},{"q":"Барлығын белгілеу пернелері:","options":["Ctrl + A","Ctrl + B","Ctrl + E","Tab"],"answer":0,"explain":"Ctrl + A — Select All."}]}'::jsonb, 1)
