insert into public.games (slug, title, description, type, category, difficulty, xp_reward, data, sort) values ('mistake-html', 'Қатені тап: HTML және CSS', 'Кодтағы қате жолды тауып, шертіп белгіле.', 'find_mistake', 'html_css', 'medium', 80, '{"items":[{"lang":"html","task":"Тақырып дұрыс көрсетілмейді.","code":["<body>","  <h1>Менің сайтым</h2>","  <p>Қош келдіңіз!</p>","</body>"],"wrong_line":1,"explain":"Ашылатын <h1> тегі </h1> тегімен жабылуы керек.","fix":"  <h1>Менің сайтым</h1>"},{"lang":"html","task":"Сурет шықпайды.","code":["<div>","  <img scr=\"robot.png\" alt=\"Робот\">","  <p>Біздің робот</p>","</div>"],"wrong_line":1,"explain":"Суреттің мекенжайы src атрибутымен жазылады, scr емес.","fix":"  <img src=\"robot.png\" alt=\"Робот\">"},{"lang":"css","task":"Мәтін түсі өзгермейді.","code":["p {","  font-size: 18px;","  colour: purple;","}"],"wrong_line":2,"explain":"CSS-те қасиет атауы color деп жазылады.","fix":"  color: purple;"},{"lang":"css","task":"Стиль мүлдем жұмыс істемейді.","code":[".card {","  padding: 16px","  border-radius: 12px;","}"],"wrong_line":1,"explain":"Әр CSS ережесінен кейін нүктелі үтір (;) қойылуы керек.","fix":"  padding: 16px;"},{"lang":"html","task":"Сілтеме басылмайды.","code":["<nav>","  <a link=\"about.html\">Біз туралы</a>","</nav>"],"wrong_line":1,"explain":"Сілтеме мекенжайы href атрибутымен беріледі.","fix":"  <a href=\"about.html\">Біз туралы</a>"}]}'::jsonb, 8)
  on conflict (slug) do nothing;
insert into public.games (slug, title, description, type, category, difficulty, xp_reward, data, sort) values ('mistake-python', 'Қатені тап: Python', 'Python бағдарламаларындағы қателерді анықта.', 'find_mistake', 'python', 'hard', 90, '{"items":[{"lang":"python","task":"Бағдарлама іске қосылмайды.","code":["age = 12","if age > 10","    print(\"Сен үлкенсің!\")"],"wrong_line":1,"explain":"if шартынан кейін қос нүкте (:) қойылуы керек.","fix":"if age > 10:"},{"lang":"python","task":"Мәтін шығарғанда қате шығады.","code":["name = \"Арман\"","print(\"Сәлем, \" + Name)"],"wrong_line":1,"explain":"Python бас және кіші әріптерді ажыратады: name мен Name — әртүрлі айнымалы.","fix":"print(\"Сәлем, \" + name)"},{"lang":"python","task":"Цикл ішіндегі команда орындалмайды.","code":["for i in range(3):","print(i)","print(\"Бітті\")"],"wrong_line":1,"explain":"Цикл денесі шегініспен (4 бос орын) жазылуы керек.","fix":"    print(i)"},{"lang":"python","task":"Сандарды қосқанда қате шығады.","code":["a = input(\"Сан: \")","b = 5","print(a + b)"],"wrong_line":0,"explain":"input() мәтін қайтарады. Санға айналдыру үшін int() қолдану керек.","fix":"a = int(input(\"Сан: \"))"}]}'::jsonb, 9)
  on conflict (slug) do nothing;
insert into public.games (slug, title, description, type, category, difficulty, xp_reward, data, sort) values ('tf-cyber', 'Ақиқат па, жалған ба: Киберқауіпсіздік', 'Интернеттегі қауіпсіздік туралы тұжырымдарды тексер.', 'true_false', 'cybersecurity', 'easy', 60, '{"statements":[{"text":"Құпиясөзді досыңа айтуға болады, егер ол сенімді болса.","answer":false,"explain":"Құпиясөзді ешкімге айтпау керек — тіпті жақын досқа да."},{"text":"Екі факторлы аутентификация аккаунтты қосымша қорғайды.","answer":true,"explain":"Құпиясөзден бөлек код қажет болғандықтан, бұзу әлдеқайда қиын."},{"text":"Белгісіз адамнан келген сілтемені бірден ашқан дұрыс.","answer":false,"explain":"Мұндай сілтемелер фишингке немесе вирусқа апаруы мүмкін."},{"text":"Антивирусты үнемі жаңартып отыру керек.","answer":true,"explain":"Жаңа вирустар күн сайын пайда болады, базаны жаңарту маңызды."},{"text":"Қоғамдық Wi-Fi арқылы банк картасын енгізу әрқашан қауіпсіз.","answer":false,"explain":"Ашық желілерде деректерді ұстап алу қаупі жоғары."},{"text":"HTTPS бар сайттар деректерді шифрлап жібереді.","answer":true,"explain":"HTTPS байланысты шифрлайды, бірақ сайттың өзін де тексеру керек."},{"text":"Әлеуметтік желіде үй мекенжайыңды жариялау — қалыпты нәрсе.","answer":false,"explain":"Жеке деректерді жария етпеу керек."},{"text":"Маңызды файлдардың сақтық көшірмесін жасау пайдалы.","answer":true,"explain":"Сақтық көшірме файлды жоғалтудан қорғайды."}]}'::jsonb, 10)
  on conflict (slug) do nothing;
